#!/usr/bin/env python3
"""One-shot exact upgrade of committed package-index generators to schema v2."""

from __future__ import annotations

import base64
import gzip
import hashlib
import json
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
EXPECTED_BLOBS = {
    "scripts/code_navigation_lib/package_docs.py": "b60712776184b833433d0d929e9b471fa0ccfad3",
    "scripts/code_navigation_lib/prototype_docs.py": "b8d5053aecaa36912f0b061dde058127062414dc",
}
RAW_SHA256 = "0c8e77586c249adde17e3c6654da277b832ab601252ea44a131de7942191e04b"
PAYLOAD = """"""


def main() -> int:
    compressed = base64.b64decode(PAYLOAD, validate=True)
    raw = gzip.decompress(compressed)
    if hashlib.sha256(raw).hexdigest() != RAW_SHA256:
        raise SystemExit("index-generator payload digest mismatch")
    decoded = json.loads(raw.decode("utf-8"))
    if set(decoded) != set(EXPECTED_BLOBS):
        raise SystemExit("index-generator payload path set mismatch")

    for relative, expected_blob in EXPECTED_BLOBS.items():
        path = ROOT / relative
        actual_blob = subprocess.check_output(
            ["git", "-C", str(ROOT), "hash-object", relative],
            text=True,
        ).strip()
        if actual_blob != expected_blob:
            raise SystemExit(
                f"index-generator source moved: {relative} "
                f"expected={expected_blob} actual={actual_blob}"
            )
        content = decoded[relative]
        if not isinstance(content, str):
            raise SystemExit(f"index-generator payload is not text: {relative}")
        compile(content, relative, "exec")
        path.write_text(content, encoding="utf-8", newline="")

    print(
        "PACKAGE_INDEX_GENERATOR_UPGRADE: PASS "
        f"files={len(EXPECTED_BLOBS)} payload_sha256={RAW_SHA256}"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
